import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    response = requests.get(url, params=parameters, headers=HEADERS)
    if response.status_code != 200:
        raise Exception("Unable to access URL or invalid response")
    try:
        data = json.loads(response.text)
    except json.JSONDecodeError:
        raise Exception("Invalid JSON data")
    if not data:
        raise Exception("Empty data")
    df = pd.DataFrame(data)
    if df.empty or not any(df.dtypes.apply(lambda x: pd.api.types.is_numeric_dtype(x))):
        raise Exception("Invalid or non-numeric data")
    corr_matrix = df.corr()
    ax = sns.heatmap(corr_matrix, annot=True, cmap='coolwarm')
    return df, ax

